using System;
using System.Collections.Generic;
using System.Linq;
using System.Drawing;
using System.Windows.Forms;
namespace DeadlockOverlay {
 public sealed class ScoutController:IDisposable {
  [System.Runtime.InteropServices.DllImport("user32.dll")] static extern bool ShowWindow(IntPtr handle,int command);
  readonly PartyMarkers markers=new PartyMarkers(System.IO.Path.Combine(SettingsManager.Folder,"scout-cache","party-markers.json"));readonly Settings settings;readonly SettingsWindow window;readonly ScoutService service;readonly Timer timer=new Timer{Interval=1000};
  ScoutRow[] roster=new ScoutRow[0];string session="",phase="";bool ended;string opened="",openedMonitor="";int revision=-1;string decorationKey="";DateTime received,nextStateRead;Dictionary<string,object> pending;
  public static int SecondaryMonitor(Rectangle game,Rectangle[] monitors,string[] names,string preferred){if(game.IsEmpty||monitors.Length<2)return -1;int gameIndex=Enumerable.Range(0,monitors.Length).OrderByDescending(i=>{var r=Rectangle.Intersect(game,monitors[i]);return (long)r.Width*r.Height;}).First();for(int i=0;i<monitors.Length;i++)if(i!=gameIndex&&names[i]==preferred)return i;for(int i=0;i<monitors.Length;i++)if(i!=gameIndex)return i;return -1;}
  public ScoutController(Settings s,SettingsWindow w){settings=s;window=w;service=new ScoutService(System.IO.Path.Combine(SettingsManager.Folder,"scout-cache"));window.Scout.Service=service;window.Scout.Options=s.Scout;timer.Tick+=(a,e)=>Tick();timer.Start();}
  public void Observe(Dictionary<string,object> raw){pending=raw;}
  public void ObserveState(MatchState state){var local=state.Players.Values.FirstOrDefault(p=>p.Local);window.Scout.UserTeam=local==null?(int?)null:local.Team;if(DateTime.UtcNow<nextStateRead)return;nextStateRead=DateTime.UtcNow.AddSeconds(1);if(!state.Demo&&settings.Scout.Network){AssetLibrary.EnsureHeroes(state.Players.Values.Select(p=>p.Hero));AssetLibrary.EnsureTeamIcons();}if((DateTime.UtcNow-received).TotalSeconds<4||state.Demo)return;if(state.Players.Count>0){var rows=state.Players.Values.Select(p=>new ScoutRow{Account=PlayerInsightEngine.AccountId(p.SteamId),Hero=p.Hero,Team=p.Team,Slot=p.Slot,Name=p.Name}).Where(p=>p.Account>0).ToArray();SetRoster(state.MatchId,rows,state.Phase);}if(LocalSnapshot.Ended(state.Phase)){ended=true;phase=L.Choose("Match ended","Матч завершён");}}
  void SetRoster(string key,ScoutRow[] rows,string state){if(rows.Length==0)return;if(key!=session){ScoutDecorations.Publish(new Dictionary<long,ScoutDecoration>());service.SetEnabled(false);session=key;ended=false;}roster=rows.GroupBy(r=>r.Account).Select(g=>g.First()).Take(12).ToArray();phase=state=="GameInProgress"?L.Choose("In match","В матче"):LocalSnapshot.Ended(state)?L.Choose("Match ended","Матч завершён"):L.Choose("Roster available · ","Состав доступен · ")+state;ended=LocalSnapshot.Ended(state);}
  void Tick(){
   var o=settings.Scout;service.SetEnabled(o.Enabled&&o.Network&&!ended);
   if(!o.Enabled){window.Scout.Options=o;window.Scout.RefreshProfile();window.Scout.Phase=L.Choose("Scout disabled","Scout отключён");ScoutDecorations.Publish(new Dictionary<long,ScoutDecoration>());window.Scout.Invalidate();return;}
   if(pending!=null){var raw=pending;pending=null;received=DateTime.UtcNow;var kind=Json.Str(raw,"kind");if(kind=="snapshot"){var localRaw=(Json.Get(raw,"players") as object[]??new object[0]).Select(Json.Obj).FirstOrDefault(p=>Json.Bool(p,"is_local"));window.Scout.UserTeam=localRaw==null?(int?)null:(int?)Json.Number(localRaw,"team");
     var rows=(Json.Get(raw,"players") as object[]??new object[0]).Select(Json.Obj).Select(p=>new ScoutRow{Account=PlayerInsightEngine.AccountId(Json.Str(p,"steam_id")),Team=(int)(Json.Number(p,"team")??0),Hero=(int)(Json.Number(p,"hero_id")??0),Slot=(int)(Json.Number(p,"slot")??0),Name=Json.Str(p,"name")}).Where(p=>p.Account>0&&(p.Team==2||p.Team==3)).ToArray();
     SetRoster(Json.Str(raw,"match_id")+":"+Json.Str(raw,"session"),rows,Json.Str(raw,"phase"));if(LocalSnapshot.Ended(Json.Str(raw,"phase")))ended=true;
    }else if(kind=="idle"){ended=true;phase=L.Choose("Waiting for roster / last session","Ожидание состава / предыдущий сеанс");}else phase=L.Choose("Local source unavailable","Локальный источник недоступен");}
   service.SetEnabled(o.Network&&!ended);if(!ended)service.Enqueue(roster.Select(r=>r.Account));
   string decorKey=o.Sample+":"+o.SmurfPercent+":"+o.Leaves+":"+o.DisabledTags+":"+session+":"+service.Revision+":"+L.Language+":"+string.Join(",",roster.Select(r=>r.Account+"/"+r.Team+"/"+r.Hero));
   if(decorKey!=decorationKey){decorationKey=decorKey;var parties=PartyDetectionService.Analyze(roster,service.Get,new CurrentPartyEvidence[0],0,DateTime.UtcNow);markers.Assign(session.Split(':')[0],parties);var decorations=new Dictionary<long,ScoutDecoration>();foreach(var row in roster){var p=service.Get(row.Account);decorations[row.Account]=new ScoutDecoration{Hero=row.Hero,Tags=PlayerInsightEngine.Ordered(PlayerInsightEngine.Analyze(p,row.Hero,o)).Take(3).ToArray(),Badge=p.Badge,RankPath=service.RankImage(p.Badge),RankFetched=p.RankFetched,Party=parties[row.Account]};}ScoutDecorations.Publish(decorations);window.Scout.Parties=parties;}
   if(o.Network&&roster.Length>0){AssetLibrary.EnsureHeroes(roster.Select(r=>r.Hero));AssetLibrary.EnsureTeamIcons();}window.Scout.Rows=roster;window.Scout.Options=o;window.Scout.Phase=phase+(o.Network?"":L.Choose(" · offline"," · без сети"));
   window.Scout.RefreshProfile();
   if(window.Scout.Visible||revision!=service.Revision){revision=service.Revision;window.Scout.Invalidate();}
   var screens=Screen.AllScreens;if(openedMonitor.Length>0&&!screens.Any(s=>s.DeviceName==openedMonitor)){window.Hide();openedMonitor="";opened="";}if(screens.Length<2)return;var game=Native.OverlayGameBounds();if(game.IsEmpty)return;int targetIndex=SecondaryMonitor(game,screens.Select(s=>s.Bounds).ToArray(),screens.Select(s=>s.DeviceName).ToArray(),o.Monitor);var target=targetIndex<0?null:screens[targetIndex];
   if(o.AutoOpen&&!ended&&roster.Length>0&&opened!=session&&target!=null){var previousFocus=Native.GetForegroundWindow();opened=session;openedMonitor=target.DeviceName;window.SelectPage(6);var a=target.WorkingArea;window.StartPosition=FormStartPosition.Manual;window.Bounds=new Rectangle(a.Left+12,a.Top+12,Math.Min(Math.Max(window.Width,(int)(1320*window.DeviceDpi/96f)),a.Width-24),Math.Min(Math.Max(window.Height,(int)(1020*window.DeviceDpi/96f)),a.Height-24));if(!window.Visible)window.Show();ShowWindow(window.Handle,4);Native.SetWindowPos(window.Handle,IntPtr.Zero,window.Left,window.Top,window.Width,window.Height,0x10|0x4|0x40);Log.Write("Scout auto-display: target="+target.DeviceName+" game="+game+" focusUnchanged="+(previousFocus==Native.GetForegroundWindow()));}
  }
  public void Dispose(){ScoutDecorations.Publish(new Dictionary<long,ScoutDecoration>());timer.Stop();timer.Dispose();service.Dispose();}
 }
}
